using System.Numerics;
using System.Runtime.InteropServices;

namespace ProdOp;

public static class MathOps
{
    /// <summary>Computes the product of all elements.</summary>
    public static float Product(ReadOnlySpan<float> values)
    {
        if (values.IsEmpty) return 0f;

        int i = 0;

        if (Vector.IsHardwareAccelerated && values.Length >= Vector<float>.Count)
        {
            var vecs = MemoryMarshal.Cast<float, Vector<float>>(values);

            // Use two accumulators to hide multiply latency
            var acc0 = Vector<float>.One;
            var acc1 = Vector<float>.One;

            int pairs = vecs.Length & ~1;
            for (int j = 0; j < pairs; j += 2)
            {
                acc0 *= vecs[j];
                acc1 *= vecs[j + 1];
            }

            if ((vecs.Length & 1) != 0)
                acc0 *= vecs[^1];

            acc0 *= acc1;

            // Horizontal reduce across vector lanes
            float product = 1f;
            for (int k = 0; k < Vector<float>.Count; k++)
                product *= acc0[k];

            i = vecs.Length * Vector<float>.Count;

            // Scalar tail
            for (; i < values.Length; i++)
                product *= values[i];

            return product;
        }

        // Scalar fallback with 4x unroll
        float p0 = 1f, p1 = 1f, p2 = 1f, p3 = 1f;
        int limit = values.Length - 3;
        for (; i < limit; i += 4)
        {
            p0 *= values[i];
            p1 *= values[i + 1];
            p2 *= values[i + 2];
            p3 *= values[i + 3];
        }
        float result = (p0 * p1) * (p2 * p3);
        for (; i < values.Length; i++)
            result *= values[i];
        return result;
    }
}

