         for (; i < limit; i += 4)
         {
             p0 *= values[i];
             p1 *= values[i + 1];
             p2 *= values[i + 2];
             p3 *= values[i + 3];
         }
         float result = (p0 * p1) * (p2 * p3);
         for (; i < values.Length; i++)
             result *= values[i];
         return result;
     }
 }
